function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
const rng=mulberry32(42);
const N=50;
function peak(times){const buckets={};for(const t of times){const s=Math.floor(t);buckets[s]=(buckets[s]||0)+1}return Math.max(...Object.values(buckets))}
const fixed=Array.from({length:N},()=>30);
const jittered=Array.from({length:N},()=>30+rng()*10);
const peakFixed=peak(fixed);
const peakJittered=peak(jittered);
console.log('fixed peak probes/sec: '+peakFixed);
console.log('jittered peak probes/sec: '+peakJittered);
console.log(peakJittered < peakFixed ? 'jitter desynchronized the herd' : 'no improvement');
